import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.DU2spEDf.js";const u=JSON.parse('{"title":"Core Features","description":"","frontmatter":{},"headers":[],"relativePath":"core-features.md","filePath":"core-features.md","lastUpdated":1787906606000}'),o={name:"core-features.md"};function d(s,e,n,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h1><p>This page consolidates Ishuko&#39;s key features.</p><h2 id="_1-computer-vision-quality-grading" tabindex="-1">1. Computer Vision Quality Grading <a class="header-anchor" href="#_1-computer-vision-quality-grading" aria-label="Permalink to &quot;1. Computer Vision Quality Grading&quot;">​</a></h2><ul><li>Ishuko uses AI to analyze photos of produce and assign an objective quality grade.</li><li>Grades are predefined; every image of maize is classified based on color, insect damage, and broken grains.</li><li>A user snaps a photo of a sample placed on a dark, high-contrast mat; the YOLOv8 neural network runs a multi-point quality check: <ol><li><strong>Damage Detection</strong> — identifies and counts physical surface defects (bruising, punctures, insect bites, mechanical damage).</li><li><strong>Maturity &amp; Color Grading</strong> — analyzes color distribution to determine ripeness.</li><li><strong>Pest Detection (e.g. weevils)</strong> — reduces quality and lowers the overall grade.</li></ol></li></ul><p><strong>Technical approach:</strong> Computer Vision AI + timestamped image metadata. See <a href="/TechDex_Technical_Documentation/ai-quality-module">AI Quality Assessment Module</a> for the full pipeline.</p><h2 id="_2-grade-assignment-metrics" tabindex="-1">2. Grade Assignment Metrics <a class="header-anchor" href="#_2-grade-assignment-metrics" aria-label="Permalink to &quot;2. Grade Assignment Metrics&quot;">​</a></h2><p>A strict <strong>weakest-link</strong> evaluation applies: if any single defect parameter crosses a threshold tier boundary, the entire batch drops to that lower grade.</p><table tabindex="0"><thead><tr><th>Quality Parameter (Defect Class)</th><th>Grade A (Excellent)</th><th>Grade B (Good)</th><th>Grade C (Average)</th><th>Grade D (Poor)</th><th>Reject</th></tr></thead><tbody><tr><td>Insect / Pest Damage</td><td>&lt; 3.0%</td><td>&lt; 6.0%</td><td>&lt; 9.0%</td><td>&lt; 15.0%</td><td>≥ 15.0%</td></tr><tr><td>Discolored / Moldy Grain</td><td>&lt; 3.0%</td><td>&lt; 6.0%</td><td>&lt; 9.0%</td><td>&lt; 15.0%</td><td>≥ 15.0%</td></tr><tr><td>Broken / Chipped Grains</td><td>&lt; 6.0%</td><td>&lt; 7.0%</td><td>&lt; 8.0%</td><td>&lt; 9.0%</td><td>≥ 9.0%</td></tr><tr><td>Extraneous Matter (stones, cob fragments)</td><td>&lt; 1.0%</td><td>&lt; 1.5%</td><td>&lt; 2.0%</td><td>&lt; 2.5%</td><td>≥ 2.5%</td></tr></tbody></table><h2 id="_3-dynamic-pricing-engine" tabindex="-1">3. Dynamic Pricing Engine <a class="header-anchor" href="#_3-dynamic-pricing-engine" aria-label="Permalink to &quot;3. Dynamic Pricing Engine&quot;">​</a></h2><ul><li>Once a grade is assigned, price is calculated from <strong>live market prices</strong> pulled from the <a href="https://data.humdata.org/dataset/wfp-food-prices-for-zambia" target="_blank" rel="noreferrer">UN WFP Humanitarian Data Exchange — Zambia Food Prices</a>.</li><li>Price modifiers by grade (per the PRD): Excellent = market price, Good = −5%, Average = −15%, Poor = −25%.</li><li>The AI technical brief&#39;s reference implementation uses: Grade A ×1.10, Grade B ×1.00, Grade C ×0.90, Grade D ×0.75, Reject ×0.50 — reconcile these two schemes before launch.</li><li>The displayed price includes the platform fee, which the cooperative is shown transparently. <strong>Platform fee: 2% of total price.</strong></li></ul><p><strong>Technical approach:</strong> price is computed server-side from the grade + the latest WFP price snapshot and stored on the produce listing (<code>price_per_kg</code>).</p><h2 id="_4-escrow-backed-transactions" tabindex="-1">4. Escrow-Backed Transactions <a class="header-anchor" href="#_4-escrow-backed-transactions" aria-label="Permalink to &quot;4. Escrow-Backed Transactions&quot;">​</a></h2><ul><li>A temporary escrow account holds buyer funds until the sale is settled, building trust between buyer and cooperative.</li><li>Buyers deposit money into escrow after placing an order.</li><li>At pickup, the buyer gives a 6-digit code to the cooperative manager.</li><li>When the cooperative manager enters the code, funds are released instantly to their account and the buyer can collect the order.</li></ul><p><strong>Technical approach:</strong> Escrow account API + a deterministic backend timer for automated release / expiry handling. Backed by the <code>payment</code> table&#39;s <code>escrow_status</code> (<code>HELD</code>, <code>DISBURSED</code>, <code>REFUNDED</code>).</p><h2 id="_5-secure-dispatch-notifications-otp" tabindex="-1">5. Secure Dispatch Notifications (OTP) <a class="header-anchor" href="#_5-secure-dispatch-notifications-otp" aria-label="Permalink to &quot;5. Secure Dispatch Notifications (OTP)&quot;">​</a></h2><ul><li>After funds are deposited, the buyer receives a notification with the cooperative&#39;s location and a 6-digit code.</li><li>The code is a cryptographically random, hashed OTP dispatched via mobile notification/SMS gateway.</li><li>The code expires within <strong>7 days</strong>; if the buyer has not collected produce by then, they are refunded with a <strong>5% cancellation penalty</strong> (compensating the cooperative for wasted time).</li></ul><p><strong>Technical approach:</strong> SMS gateway API + cryptographic token library for single-use code generation, validated against a stored hash server-side.</p><h2 id="_6-marketplace" tabindex="-1">6. Marketplace <a class="header-anchor" href="#_6-marketplace" aria-label="Permalink to &quot;6. Marketplace&quot;">​</a></h2><ul><li>Bridges cooperative managers and wholesale buyers.</li><li>Displays what each cooperative is selling, including price, grade, and quantity — buyers cannot purchase a partial quantity of a listing.</li><li>Buyers select a pickup date <strong>within 7 days</strong> of order placement; dates outside that window are disabled in the UI.</li></ul><h2 id="feature-summary-table" tabindex="-1">Feature Summary Table <a class="header-anchor" href="#feature-summary-table" aria-label="Permalink to &quot;Feature Summary Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th><th>Technical Approach</th></tr></thead><tbody><tr><td>Computer Vision Quality Grading</td><td>Analyzes timestamped photos to assign an objective grade (A–D)</td><td>Computer Vision AI (OpenCV + YOLOv8), timestamped image metadata</td></tr><tr><td>Escrow-Backed Transactions</td><td>Buyer funds held in escrow, released on 6-digit code match at pickup</td><td>Escrow Account API, deterministic backend timer for automated release</td></tr><tr><td>Secure Dispatch Notifications</td><td>6-digit OTP sent to buyer to confirm produce pickup</td><td>SMS gateway API</td></tr><tr><td>Dynamic Pricing Engine</td><td>Market-price-linked, grade-adjusted pricing with a 2% platform fee</td><td>Live WFP HDX price feed + grade modifier lookup</td></tr><tr><td>Marketplace</td><td>Cooperative listings browsable by grade, price, and quantity</td><td>Produce listing API + 7-day pickup date constraint</td></tr></tbody></table>',21)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
